import urllib.request
import urllib.error
import time


class RateLimitError(Exception):
    pass


class ServerError(Exception):
    pass


class ClientError(Exception):
    pass


class ConnectionError(Exception):
    pass


class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path):
        url = self.base_url + path

        # 429 retry logic
        for attempt in range(3):
            try:
                req = urllib.request.Request(url)
                response = urllib.request.urlopen(req, timeout=self.timeout)
                return response.read().decode('utf-8')
            except urllib.error.HTTPError as e:
                if e.code == 429:
                    if attempt < 2:
                        wait_time = 0.5 * (2 ** attempt)
                        time.sleep(wait_time)
                        continue
                    else:
                        raise RateLimitError(f"Rate limited after 3 attempts: {e}")
                elif 500 <= e.code < 600:
                    # 5xx retry once
                    time.sleep(1)
                    try:
                        req = urllib.request.Request(url)
                        response = urllib.request.urlopen(req, timeout=self.timeout)
                        return response.read().decode('utf-8')
                    except urllib.error.HTTPError as e2:
                        raise ServerError(f"Server error after retry: {e2}")
                elif 400 <= e.code < 500:
                    raise ClientError(f"Client error: {e}")
            except urllib.error.URLError as e:
                # Network error retry once
                time.sleep(1)
                try:
                    req = urllib.request.Request(url)
                    response = urllib.request.urlopen(req, timeout=self.timeout)
                    return response.read().decode('utf-8')
                except urllib.error.URLError as e2:
                    raise ConnectionError(f"Connection error after retry: {e2}")

        # This should not be reached due to the raise in the 429 block
        raise RateLimitError("Rate limited after 3 attempts")
